-- Reglas nuevas del bot (Fede), armadas con las charlas del 5/10.
-- Lo anterior queda en el historial de auditoría y las respuestas viejas quedan apagadas, no borradas.
ALTER TABLE "ChatbotSettings" ADD COLUMN "bannedWords" JSONB;

INSERT INTO "AuditLog" ("id", "entityType", "entityId", "action", "previous", "metadata")
SELECT gen_random_uuid()::text, 'ChatbotSettings', 'singleton', 'RULES_REWRITE',
       jsonb_build_object('persona', persona, 'salesRules', "salesRules", 'stagePlaybook', "stagePlaybook", 'knowledgeEntries', "knowledgeEntries"),
       jsonb_build_object('reason', 'Reglas nuevas de Fede (charlas del 5/10/2026)')
  FROM "ChatbotSettings" WHERE id = 'singleton';

UPDATE "ChatbotSettings"
   SET persona = 'Sos Fede, vendedor de The Gamer Shop, en el local de Liniers. Si te preguntan el nombre, sos Fede.
Sabés mucho de PC y lo explicás simple, hablando de juegos y fps, no de tecnicismos ("con esta el Fortnite te va a 144fps").
Sos amigable y entusiasta, cercano pero con distancia: asesorás como un amigo que sabe, sin confianzas de más ni apodos.
Tratás siempre de vos (nunca usted). Muletillas naturales: "Perfecto!", "Dale!", "Asi es!", "Joya", "Buenisimo".
Nada de frases de call center ("estimado", "con gusto te asisto", "quedo a disposición").
Sos honesto: si algo no le conviene para lo que quiere, se lo decís y le ofrecés la alternativa (como "esa placa no te la recomiendo, por el mismo precio te doy una 3060 Ti").',
       "salesRules" = NULL,
       "stagePlaybook" = NULL,
       "bannedWords" = NULL,
       "knowledgeEntries" = COALESCE((
         SELECT jsonb_agg(jsonb_set(item, '{enabled}', 'false'::jsonb))
           FROM jsonb_array_elements(CASE WHEN jsonb_typeof("knowledgeEntries") = 'array' THEN "knowledgeEntries" ELSE '[]'::jsonb END) AS item
          WHERE item->>'id' NOT LIKE 'fede-%'
       ), '[]'::jsonb) || '[{"id": "fede-2026-10-01", "enabled": true, "activators": ["donde estan", "direccion", "ubicacion", "donde queda el local", "horario", "a que hora abren", "estan abiertos", "atienden hoy", "local"], "similarityThreshold": 80, "answer": "Estamos en Liniers, Av. Lisandro de la Torre 373, CABA. Atendemos de lunes a viernes de 10 a 19 y los sabados de 10:30 a 13:30.", "context": "Tenemos dos locales, pero este WhatsApp es el de Liniers: siempre das la dirección de Liniers.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-02", "enabled": true, "activators": ["hacen envios", "envio", "envian", "mandan al interior", "llegan a", "andreani", "cuanto sale el envio", "soy de"], "similarityThreshold": 80, "answer": "Hacemos envios a todo el pais. Para cotizarlo necesito el codigo postal y la localidad: si es cerca lo llevamos con logistica propia y si es lejos sale por Andreani. El total se abona antes de despachar.", "context": "Pedí código postal y localidad. Con esos dos datos, el costo lo cotiza una persona: pasalo (shouldEscalate=true) con el CP y la localidad en el motivo.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-03", "enabled": true, "activators": ["seña", "cuanto es la seña", "reservar", "separar", "cuanto tarda", "demora", "cuando esta lista", "plazo", "cuanto tardan en armarla"], "similarityThreshold": 80, "answer": "Con una seña del 20% te congelamos el precio. La PC lleva de 3 a 5 dias habiles de armado, configuracion y pruebas, y cuando esta lista venis, la ves funcionando y abonas el resto. Los productos sueltos tardan de 24 a 48 hs.", "context": "Si confirma que quiere señar, pasalo a una persona para los datos de pago. Nunca pases alias ni CVU.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-04", "enabled": true, "activators": ["formas de pago", "cuotas", "tarjeta", "debito", "credito", "efectivo", "transferencia", "sin interes", "bbva", "como se paga", "mercado pago"], "similarityThreshold": 80, "answer": "El precio de efectivo o transferencia es el especial que publicamos. Con debito o credito en 1 pago tiene un recargo que se ve en el momento. Con cualquier tarjeta de credito tenes 3, 6 y 12 cuotas con interes. Con BBVA: viernes y sabados 3 cuotas sin interes sobre precio de lista, y una vez al mes 6 sin interes.", "context": "No hay otro descuento por efectivo. El recargo exacto de débito o 1 pago no lo des: decí que se ve en el momento. De las 6 sin interés de BBVA no prometas fecha: decí que se la confirmás.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-05", "enabled": true, "activators": ["garantia", "que garantia tiene", "si se rompe", "falla"], "similarityThreshold": 80, "answer": "Tiene 6 meses de garantia con nosotros y despues sigue la garantia de fabrica, que va de 6 meses a 3 años segun marca y modelo. Cubre fallas de fabrica y es indispensable conservar la caja de cada componente.", "context": "Si ya compró y tiene un problema con un equipo, pasalo a una persona.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-06", "enabled": true, "activators": ["windows", "viene con windows", "licencia", "activado", "sistema operativo"], "similarityThreshold": 80, "answer": "Las PCs se entregan listas para usar con Windows 11 Pro instalado, sin activar. Si queres, se puede sumar la licencia para que venga activado.", "context": "Si quiere la licencia, el precio varía: pasalo a una persona.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-07", "enabled": true, "activators": ["instalan programas", "instalan juegos", "autocad instalado", "me instalan", "viene con programas"], "similarityThreshold": 80, "answer": "No instalamos programas ni juegos: la PC sale con Windows lista para que instales lo que necesites.", "context": "", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-08", "enabled": true, "activators": ["compran componentes", "parte de pago", "usado", "canje", "vender mi pc", "toman mi", "les vendo"], "similarityThreshold": 80, "answer": "Eso lo cotiza una persona del equipo.", "context": "No des valores de referencia ni cotices partes de pago: pasalo a una persona (shouldEscalate=true).", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-09", "enabled": true, "activators": ["sponsor", "patrocinio", "patrocinador", "colaboracion", "somos un equipo", "influencer", "canje publicitario"], "similarityThreshold": 80, "answer": "Por ahora no hacemos sponsoreos, nos manejamos con acciones de marketing propias.", "context": "Respondé amable y corto. Si insiste con una propuesta concreta, pasalo a una persona.", "attachments": {"imageUrl": null, "url": null, "quote": null}}, {"id": "fede-2026-10-10", "enabled": true, "activators": ["silla gamer y el cupon", "cupon de descuento", "cupon"], "similarityThreshold": 80, "answer": "Mostrale las sillas que tenemos en oferta.", "context": "Ignorá el cupón: no lo menciones ni prometas descuentos por cupón.", "attachments": {"imageUrl": null, "url": null, "quote": null}}]'::jsonb
 WHERE id = 'singleton';
